class Solution { fun subStrHash(s:String,power:Int,modulo:Int,k:Int,hashValue:Int):String{var powerK=1L;repeat(k){powerK=powerK*power%modulo};var hash=0L;var answer=0;for(i in s.length-1 downTo 0){hash=(hash*power+(s[i]-'a'+1))%modulo;if(i+k<s.length)hash=(hash-(s[i+k]-'a'+1)*powerK%modulo+modulo)%modulo;if(i<=s.length-k&&hash==hashValue.toLong())answer=i};return s.substring(answer,answer+k)} }
